import {liveRecord} from './record-tools.js';
import {packingTotals} from './packing-math.js';
export const clone=x=>JSON.parse(JSON.stringify(x));export const uid=()=>globalThis.crypto.randomUUID();export const money=n=>(n/100).toFixed(2);
export function monthKey(date){const p=new Intl.DateTimeFormat('en',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit'}).formatToParts(new Date(date));return `${p.find(x=>x.type==='year').value}-${p.find(x=>x.type==='month').value}`;}
export function deadline(month){const [y,m]=month.split('-').map(Number);return new Date(Date.UTC(y,m,3,15,59,59,999)).toISOString();}
export const overdue=(r,now=new Date())=>liveRecord(r)&&r.status!=='confirmed'&&+new Date(now)>+new Date(deadline(r.serviceMonth));
const int=(n,min=0)=>Number.isSafeInteger(n)&&n>=min;function need(ok,msg){if(!ok)throw Error(msg);}function role(a,roles){need(a&&a.active!==false&&roles.includes(a.role),'Permission denied.');}
export function productCheck(p){need(p.id&&p.code&&p.name,'Product ID, code and name are required.');need(int(p.supplierSize,1)&&int(p.rpUnit,1)&&int(p.ninsoSize,1),'Pack sizes must be positive integers.');need(int(p.rateMicros),'Rate must be non-negative, at most 6 decimals.');need(typeof p.barcode==='string','Barcode must be text.');}
export const linePcs=(p,ctn,loose)=>{need(int(ctn)&&int(loose)&&loose<p.ninsoSize,'Enter whole CTN and loose PCS below carton size.');const n=ctn*p.ninsoSize+loose;need(int(n,1),'Quantity must be greater than zero.');return n;};
export function remaining(s,t){if(!liveRecord(t))return 0;if(Number.isFinite(t.receivedPcs))return t.expected-t.receivedPcs-(t.approvedLossRaw||0)/t.rpUnit;return t.expected-(s.adjustments||[]).filter(a=>a.taskId===t.id&&a.status==='confirmed').reduce((n,a)=>n+a.pcs,0)-s.returns.filter(r=>r.taskId===t.id&&liveRecord(r)).reduce((a,r)=>a+r.pcs,0)-s.losses.filter(l=>l.taskId===t.id&&l.status==='approved').reduce((a,l)=>a+l.rawQty/t.rpUnit,0);}
export function allocate(s,packerId,productId,pcs){let left=pcs;const result=[];const tasks=s.tasks.filter(t=>t.packerId===packerId&&t.productId===productId).sort((a,b)=>a.occurredAt.localeCompare(b.occurredAt)||a.id.localeCompare(b.id));for(const t of tasks){const qty=Math.min(Math.floor(remaining(s,t)+1e-9),left);if(qty>0){result.push({task:t,pcs:qty});left-=qty;}if(!left)break;}need(left===0,'Received quantity exceeds available tasks. Administration review required.');return result;}
export function apply(s,cmd,actor,now=new Date().toISOString()){
 if(s.commands.includes(cmd.id))return s;need(cmd.id&&cmd.type,'Invalid command.');const x=cmd.payload||{};const audit={id:cmd.id,actorId:actor?.id,at:now,type:cmd.type};
 if(cmd.type==='deliver'){
 role(actor,['driver']);const packer=s.users.find(u=>u.id===x.packerId&&u.role==='packer'&&u.active);need(packer,'Select an active packer.');need(x.items?.length,'Add a product.');const seen=new Set();need(Number.isFinite(Date.parse(x.occurredAt))&&Date.parse(x.occurredAt)<=Date.parse(now)+300000,'Invalid delivery time.');
 for(const [i,item] of x.items.entries()){const p=s.products.find(p=>p.id===item.productId&&p.active);need(p&&p.barcode,'Unknown or inactive barcode.');need(!seen.has(p.id),'Combine duplicate products.');seen.add(p.id);need(int(item.ctn,1),'CTN must be a positive integer.');const effective=(history,fallback)=>(history||[]).filter(v=>v.at<=x.occurredAt).sort((a,b)=>b.at.localeCompare(a.at))[0]?.value??fallback;const base=effective(p.rateHistory,p.rateMicros),extra=effective(packer.extraHistory,packer.extraMicros);s.tasks.push({id:`${cmd.id}-${i}`,orderId:cmd.id,productId:p.id,productCode:p.code,productName:p.name,packerId:packer.id,driverId:actor.id,ctn:item.ctn,expected:item.ctn*p.supplierSize/p.rpUnit,supplierSize:p.supplierSize,rpUnit:p.rpUnit,ninsoSize:p.ninsoSize,rateMicros:base+extra,baseMicros:base,extraMicros:extra,occurredAt:x.occurredAt,uploadedAt:now});}
 }else if(cmd.type==='receive'){
 role(actor,['driver']);need(x.items?.length,'Add a product.');need(Number.isFinite(Date.parse(x.occurredAt))&&Date.parse(x.occurredAt)<=Date.parse(now)+300000,'Invalid collection time.');const seen=new Set();
 for(const [i,item] of x.items.entries()){need(!seen.has(item.productId),'Combine duplicate products.');seen.add(item.productId);const tasks=s.tasks.filter(t=>liveRecord(t)&&t.productId===item.productId&&t.packerId===x.packerId);need(tasks.length,'No matching delivery.');const size=tasks[0].ninsoSize;need(tasks.every(t=>t.ninsoSize===size),'Carton-size mismatch. Ask administration.');const pcs=linePcs({ninsoSize:size},item.ctn,item.loose);for(const [j,a] of allocate(s,x.packerId,item.productId,pcs).entries()){const t=a.task;s.returns.push({id:`${cmd.id}-${i}-${j}`,collectionId:cmd.id,taskId:t.id,productId:t.productId,productName:t.productName,productCode:t.productCode,packerId:x.packerId,driverId:actor.id,pcs:a.pcs,ninsoSize:t.ninsoSize,rateMicros:t.rateMicros,amountCents:Math.round(a.pcs*t.rateMicros/10000),occurredAt:x.occurredAt,uploadedAt:now,serviceMonth:monthKey(x.occurredAt),status:'pending',version:1,settlementId:null});}}
 }else if(cmd.type==='loss'){
 role(actor,['driver']);const t=s.tasks.find(t=>t.id===x.taskId);need(t,'Task not found.');need(['damaged','missing'].includes(x.reason)&&['raw','finished'].includes(x.unit),'Select reason and unit.');need(int(x.qty,1)&&x.note?.trim(),'Quantity and reason are required.');const rawQty=x.qty*(x.unit==='finished'?t.rpUnit:1);const pending=s.losses.filter(l=>l.taskId===t.id&&l.status==='pending').reduce((a,l)=>a+l.rawQty,0);need(rawQty+pending<=Math.round(remaining(s,t)*t.rpUnit),'Loss exceeds outstanding quantity.');s.losses.push({id:cmd.id,...x,rawQty,packerId:t.packerId,driverId:actor.id,status:'pending',at:now});
 }else if(['confirm','dispute'].includes(cmd.type)){
 role(actor,['packer']);const r=s.returns.find(r=>r.id===x.id);need(r&&r.packerId===actor.id,'Record not found.');need(r.status==='pending'&&r.version===x.version,'Record changed. Refresh and review again.');need(!r.settlementId,'Settled record is locked.');if(cmd.type==='dispute'){need(x.note?.trim(),'Explain the issue.');r.status='disputed';r.dispute=x.note;}else{r.status='confirmed';r.confirmedAt=now;r.confirmedBy=actor.id;}
 }else if(cmd.type==='resolveLoss'){
 role(actor,['admin']);const t=s.tasks.find(t=>t.id===x.taskId);need(t&&liveRecord(t),'Choose an active delivery task.');need(int(x.qty,1),'Enter a positive whole quantity in EA.');
 const remainingEA=Math.max(0,Math.round(remaining(s,t)*t.rpUnit)),pendingEA=s.losses.filter(l=>l.taskId===t.id&&l.status==='pending').reduce((n,l)=>n+l.rawQty,0);
 need(x.qty<=remainingEA-pendingEA,'Quantity exceeds unreserved remaining EA. Review pending reports first.');
 const loss={id:cmd.id,taskId:t.id,packerId:t.packerId,driverId:actor.id,qty:x.qty,unit:'raw',rawQty:x.qty,reason:'damage_loss',note:'Damage & Loss',status:'approved',source:'admin',at:now,reviewedAt:now,reviewedBy:actor.id,reviewNote:'Damage & Loss',remainingEAAfter:remainingEA-x.qty};
 s.losses.push(loss);if(Number.isFinite(t.approvedLossRaw))t.approvedLossRaw+=x.qty;audit.reason='Damage & Loss';audit.after=clone(loss);
 }else if(cmd.type==='reviewLoss'){
 role(actor,['admin']);const l=s.losses.find(l=>l.id===x.id);need(l&&l.status==='pending','Loss is no longer pending.');need(x.note?.trim(),'Review note required.');need(typeof x.approve==='boolean','Select approve or reject.');audit.before=clone(l);audit.reason=x.note;if(x.approve){const t=s.tasks.find(t=>t.id===l.taskId);need(t&&liveRecord(t),'Delivery is no longer active.');need(l.rawQty<=Math.round(remaining(s,t)*t.rpUnit),'Loss conflicts with collected quantity.');if(Number.isFinite(t.approvedLossRaw))t.approvedLossRaw+=l.rawQty;}l.status=x.approve?'approved':'rejected';l.reviewedAt=now;l.reviewedBy=actor.id;l.reviewNote=x.note;audit.after=clone(l);
 }else if(cmd.type==='correctReturn'){
 role(actor,['admin']);const r=s.returns.find(r=>r.id===x.id);need(r&&liveRecord(r)&&!r.settlementId,'Voided or settled records cannot be corrected directly.');need(int(x.pcs,1)&&int(x.rateMicros)&&x.note?.trim(),'Valid PCS, rate and correction reason required.');audit.before=clone(r);const t=s.tasks.find(t=>t.id===r.taskId);need(x.pcs<=remaining(s,t)+r.pcs,'Quantity exceeds outstanding balance.');Object.assign(r,{pcs:x.pcs,rateMicros:x.rateMicros,amountCents:Math.round(x.pcs*x.rateMicros/10000),status:'pending',version:r.version+1,correction:x.note});delete r.confirmedAt;delete r.confirmedBy;audit.after=clone(r);
 }else if(cmd.type==='correctTask'){
 role(actor,['admin']);const t=s.tasks.find(t=>t.id===x.id);need(t&&liveRecord(t)&&int(x.ctn,1)&&x.note?.trim(),'Valid task, CTN and reason required.');audit.before=clone(t);need(x.ctn*t.supplierSize/t.rpUnit>=t.expected-remaining(s,t),'Quantity is below receipts and approved losses.');t.ctn=x.ctn;t.expected=x.ctn*t.supplierSize/t.rpUnit;audit.after=clone(t);audit.reason=x.note;
 }else if(cmd.type==='deleteProduct'){
 role(actor,['admin']);need(x.note?.trim(),'A deletion reason is required.');const p=s.products.find(p=>p.id===x.id);need(p,'Product not found.');audit.before=clone(p);audit.reason=x.note;
 const used=s.tasks.some(t=>t.productId===p.id)||s.returns.some(r=>r.productId===p.id)||s.adjustments.some(a=>a.productId===p.id)||s.settlements.some(z=>z.lines.some(l=>l.productId===p.id||l.productCode===p.code));
 if(used){p.active=false;p.deactivatedAt=now;p.deactivatedBy=actor.id;p.deactivationReason=x.note;audit.result='deactivated';audit.after=clone(p);}else{s.products=s.products.filter(v=>v.id!==p.id);audit.result='deleted';}
 }else if(cmd.type==='voidReturn'){
 role(actor,['admin']);need(x.note?.trim(),'A deletion reason is required.');const r=s.returns.find(r=>r.id===x.id);need(r&&liveRecord(r),'Collection is missing or already voided.');need(!r.settlementId,'Settled collection must use a reversal adjustment.');audit.before=clone(r);audit.reason=x.note;r.status='voided';r.voidedAt=now;r.voidedBy=actor.id;r.voidReason=x.note;r.version++;
 const t=s.tasks.find(t=>t.id===r.taskId);if(Number.isFinite(t?.receivedPcs))t.receivedPcs-=r.pcs;audit.after=clone(r);
 }else if(cmd.type==='voidTask'){
 role(actor,['admin']);need(x.note?.trim(),'A deletion reason is required.');const t=s.tasks.find(t=>t.id===x.id);need(t&&liveRecord(t),'Delivery is missing or already voided.');
 const received=s.returns.filter(r=>r.taskId===t.id&&liveRecord(r)).reduce((n,r)=>n+r.pcs,0)+s.adjustments.filter(a=>a.taskId===t.id&&a.status==='confirmed').reduce((n,a)=>n+a.pcs,0);
 need(received===0&&!s.adjustments.some(a=>a.taskId===t.id&&a.status==='pending'),'Handle linked collections and pending adjustments first.');need(!s.losses.some(l=>l.taskId===t.id&&['pending','approved'].includes(l.status)),'Resolve linked loss reports before deleting this delivery.');audit.before=clone(t);audit.reason=x.note;t.status='voided';t.voidedAt=now;t.voidedBy=actor.id;t.voidReason=x.note;audit.after=clone(t);
 }else if(cmd.type==='saveProduct'){
 role(actor,['admin']);productCheck(x);Object.assign(x,packingTotals(x));need(!s.products.some(p=>p.id!==x.id&&(p.code===x.code||(x.barcode&&p.barcode===x.barcode))),'Code or barcode already exists.');const old=s.products.find(p=>p.id===x.id);if(old){need(!s.tasks.some(t=>t.productId===old.id)||(old.supplierSize===x.supplierSize&&old.rpUnit===x.rpUnit&&old.ninsoSize===x.ninsoSize),'Used product pack sizes are fixed. Create a new code.');audit.before=clone(old);const history=old.rateHistory||[{at:'1970-01-01T00:00:00.000Z',value:old.rateMicros}];if(old.rateMicros!==x.rateMicros)history.push({at:now,value:x.rateMicros});Object.assign(old,x,{rateHistory:history});}else s.products.push({...clone(x),rateHistory:[{at:'1970-01-01T00:00:00.000Z',value:x.rateMicros}]});
 }else if(cmd.type==='saveUser'){
 role(actor,['admin']);need(x.id&&x.name&&['driver','packer','admin'].includes(x.role)&&int(x.extraMicros),'Valid ID, name, role and extra rate required.');const old=s.users.find(u=>u.id===x.id);if(old){need(old.role===x.role,'Existing role cannot be changed.');need(old.id!==actor.id||x.active,'Cannot disable your own account.');audit.before=clone(old);const history=old.extraHistory||[{at:'1970-01-01T00:00:00.000Z',value:old.extraMicros}];if(old.extraMicros!==x.extraMicros)history.push({at:now,value:x.extraMicros});Object.assign(old,x,{extraHistory:history});}else s.users.push({...clone(x),extraHistory:[{at:'1970-01-01T00:00:00.000Z',value:x.extraMicros}]});
 }else if(cmd.type==='settle'){
 role(actor,['admin']);need(/^\d{4}-(0[1-9]|1[0-2])$/.test(x.month),'Select a month.');need(x.month<monthKey(now),'Wait until the service month has ended.');need(!s.settlements.some(z=>z.month===x.month),'Month already closed.');const pending=s.returns.filter(r=>liveRecord(r)&&r.serviceMonth===x.month&&r.status!=='confirmed'&&!r.settlementId);need(!pending.length||Date.parse(now)>Date.parse(deadline(x.month)),'Early closing requires all items to be confirmed.');const items=s.returns.filter(r=>!r.settlementId&&r.status==='confirmed'&&r.serviceMonth<=x.month&&(r.serviceMonth<x.month||r.confirmedAt<=deadline(x.month)));const adj=s.adjustments.filter(a=>!a.settlementId&&a.status==='confirmed'&&a.serviceMonth<=x.month);need(items.length||adj.length,'No confirmed items available.');const lines=[...items.map(r=>({returnId:r.id,packerId:r.packerId,productCode:r.productCode,productName:r.productName,serviceMonth:r.serviceMonth,pcs:r.pcs,rateMicros:r.rateMicros,amountCents:r.amountCents,supplement:r.serviceMonth<x.month})),...adj.map(a=>({returnId:a.id,packerId:a.packerId,productCode:a.productCode,productName:a.productName,serviceMonth:a.serviceMonth,pcs:a.pcs,rateMicros:a.rateMicros,amountCents:a.amountCents,supplement:true,adjustment:true}))];s.settlements.push({id:cmd.id,month:x.month,closedAt:now,closedBy:actor.id,lines,totalCents:lines.reduce((a,l)=>a+l.amountCents,0)});[...items,...adj].forEach(r=>r.settlementId=cmd.id);
 }else if(cmd.type==='adjustment'){
 role(actor,['admin']);const r=s.returns.find(r=>r.id===x.id);need(r?.settlementId&&int(x.newPcs)&&int(x.newRateMicros)&&x.note?.trim(),'Select a settled item and enter a reason.');need(!s.adjustments.some(a=>a.returnId===r.id),'Adjustment already exists.');const task=s.tasks.find(t=>t.id===r.taskId);need(x.newPcs-r.pcs<=remaining(s,task),'Adjustment exceeds outstanding quantity.');s.adjustments.push({id:cmd.id,taskId:r.taskId,returnId:r.id,packerId:r.packerId,productId:r.productId,productName:r.productName,productCode:r.productCode,serviceMonth:r.serviceMonth,originalPcs:r.pcs,originalAmountCents:r.amountCents,pcs:x.newPcs-r.pcs,rateMicros:x.newRateMicros,amountCents:Math.round(x.newPcs*x.newRateMicros/10000)-r.amountCents,note:x.note,status:'pending',version:1,at:now,settlementId:null});
 }else if(cmd.type==='confirmAdjustment'){
 role(actor,['packer']);const a=s.adjustments.find(a=>a.id===x.id);need(a&&a.packerId===actor.id&&a.status==='pending'&&a.version===x.version,'Adjustment not available.');const task=s.tasks.find(t=>t.id===a.taskId);need(a.pcs<=remaining(s,task),'Adjustment conflicts with later collections. Ask administration.');a.status='confirmed';a.confirmedAt=now;
 }else throw Error('Unknown action.');s.commands.push(cmd.id);s.audits.push(audit);return s;
}
export function execute(s,c,a,n){return apply(clone(s),c,a,n);}
export function scoped(s,a){const o=clone(s);if(a.role==='admin')return o;o.users=o.users.filter(u=>u.active&&(u.role==='packer'||u.id===a.id));o.users.forEach(u=>{delete u.extraMicros;delete u.extraHistory;delete u.ic;delete u.password;});if(a.role==='packer'){o.tasks=o.tasks.filter(t=>t.packerId===a.id);o.returns=o.returns.filter(r=>r.packerId===a.id);o.losses=o.losses.filter(l=>l.packerId===a.id);o.adjustments=o.adjustments.filter(z=>z.packerId===a.id);o.users=o.users.filter(u=>u.id===a.id);o.settlements=o.settlements.map(z=>({...z,lines:z.lines.filter(l=>l.packerId===a.id)})).map(z=>({...z,totalCents:z.lines.reduce((v,l)=>v+l.amountCents,0)}));}else{o.products.forEach(p=>{delete p.rateMicros;delete p.rateHistory;});o.tasks.forEach(t=>{delete t.rateMicros;delete t.baseMicros;delete t.extraMicros;});o.returns.forEach(r=>{delete r.rateMicros;delete r.amountCents;});o.adjustments=o.adjustments.map(a=>({id:a.id,taskId:a.taskId,pcs:a.pcs,status:a.status}));o.settlements=[];}o.audits=[];o.commands=[];return o;}
export function empty(){return {products:[],users:[],tasks:[],returns:[],losses:[],settlements:[],adjustments:[],commands:[],audits:[]};}
export function demo(){const s=empty();s.products=[{id:'p1',code:'D151070+',name:'TOKI TOMATO FLAV CORN SNACKS 60G',barcode:'9556860722138',supplierSize:60,rpUnit:2,ninsoSize:30,rateMicros:100000,bag:'TAPE',active:true},{id:'p2',code:'D151781+',name:'PREMIER FACIAL TISSUE 90S',barcode:'9556113006961',supplierSize:64,rpUnit:2,ninsoSize:32,rateMicros:120000,bag:'TAPE',active:true},{id:'p3',code:'D153355',name:'YUPI BURGER DB 1S',barcode:'8992741941006',supplierSize:432,rpUnit:5,ninsoSize:12,rateMicros:150000,bag:'5 x 8',active:true},{id:'p4',code:'D153756',name:'NESCAFE 3IN1 MILD 18G',barcode:'9556001297846',supplierSize:600,rpUnit:3,ninsoSize:25,rateMicros:80000,bag:'4 x 9',active:true}];s.users=[{id:'ADMIN',name:'Administration',role:'admin',extraMicros:0,active:true},{id:'DRV01',name:'Daniel Tan',role:'driver',extraMicros:0,active:true},{id:'DRV02',name:'Amir Rahman',role:'driver',extraMicros:0,active:true},...['Aisha','Mei Ling','Siti','Kavitha','Nurul','Wai Yee','Farah','Devi','Yvonne','Hana','Lina','Priya'].map((name,i)=>({id:`PK${String(i+1).padStart(2,'0')}`,name,role:'packer',extraMicros:i===0?20000:0,active:true}))];const at=days=>{const d=new Date();d.setDate(d.getDate()+days);d.setHours(10,0,0,0);return d.toISOString();};for(let i=0;i<5;i++){const packer=s.users.find(u=>u.id===`PK${String(i%3+1).padStart(2,'0')}`);apply(s,{id:`DEMO-D${i+1}`,type:'deliver',payload:{packerId:packer.id,occurredAt:at(-8+i),items:[{productId:s.products[i%4].id,ctn:10+i*2}]}},s.users[1],at(-8+i));if(i<3)apply(s,{id:`DEMO-R${i+1}`,type:'receive',payload:{packerId:packer.id,occurredAt:at(-2+i),items:[{productId:s.products[i%4].id,ctn:3,loose:i}]}},s.users[2],at(-2+i));}s.returns[1].status='confirmed';s.returns[1].confirmedAt=at(-1);return s;}


